blocks.text:
.btn {
  min-width: 44px; min-height: 44px;   /* 애플 44 · 구글 48 이상 */
  margin: 8px;                          /* 간격 최소 8px */
}
/* 시각은 작아도 탭 영역은 padding 으로 키운다 */
.icon-btn { padding: 12px; }            /* 작은 아이콘 주위 여백 */
/* 위험 동작(삭제·결제)은 다른 것과 멀리 */

input { font-size: 16px; }        /* 16px 미만이면 iOS 가 확대 */
<input type="email" inputmode="email" autocomplete="email">
<input type="tel" inputmode="tel">   /* 알맞은 키보드·자동완성 */

/* 안전 영역: 노치·홈 인디케이터 피하기 */
.bottom-bar { padding-bottom: env(safe-area-inset-bottom); }
.page { padding: env(safe-area-inset-top) env(safe-area-inset-right)
                 env(safe-area-inset-bottom) env(safe-area-inset-left); }
/* <meta viewport ... viewport-fit=cover> 필요 */
